import { useId, useRef, type KeyboardEvent } from "react";
import "./SegmentedControl.css";

export interface SegmentedOption<T extends string> {
  value: T;
  label: string;
}

export interface SegmentedControlProps<T extends string> {
  label: string;
  options: readonly SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
}

export function SegmentedControl<T extends string>({
  label,
  options,
  value,
  onChange,
}: SegmentedControlProps<T>) {
  const captionId = useId();
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const checkedIndex = options.findIndex((option) => option.value === value);
  // Roving tabindex: the checked option is the single tab stop.
  // If nothing matches the value, the first option takes the tab stop.
  const tabStopIndex = checkedIndex >= 0 ? checkedIndex : 0;

  function choose(index: number) {
    const option = options[index];
    if (option === undefined) return;
    if (option.value !== value) {
      onChange(option.value);
    }
  }

  function moveTo(index: number) {
    choose(index);
    buttonRefs.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const count = options.length;
    if (count === 0) return;

    let next: number | null = null;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = (index + 1) % count;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = (index - 1 + count) % count;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = count - 1;
        break;
      default:
        return;
    }

    event.preventDefault();
    moveTo(next);
  }

  return (
    <div className="segmented-control-field">
      <span id={captionId} className="segmented-control__caption">
        {label}
      </span>
      <div role="radiogroup" aria-label={label} className="segmented-control">
        {options.map((option, index) => {
          const checked = option.value === value;
          return (
            <button
              key={option.value}
              ref={(element) => {
                buttonRefs.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={index === tabStopIndex ? 0 : -1}
              className="segmented-control__option"
              onClick={() => choose(index)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
