.segmented-control-field {
  display: inline-flex;
  flex-direction: column;
  gap: 0.4em;
  font: inherit;
  color: var(--ink);
}

.segmented-control__caption {
  font-size: clamp(0.75rem, 0.7rem + 0.2vw, 0.875rem);
  color: var(--muted);
}

.segmented-control {
  display: inline-flex;
  align-items: center;
  gap: 0.25em;
  padding: 0.25em;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: var(--slide);
}

.segmented-control__option {
  font: inherit;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 1rem);
  line-height: 1.2;
  padding: 0.45em 1em;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}

.segmented-control__option:hover {
  background: var(--myelin-wash);
}

.segmented-control__option[aria-checked="true"],
.segmented-control__option[aria-checked="true"]:hover {
  background: var(--myelin);
  color: var(--slide);
}

:root[data-motion="reduce"] .segmented-control__option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .segmented-control__option {
    transition: none;
  }
}
